Lemma gr_B : forall (fx : FPState) regs (m : word -> option byte) (s bil : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (4096 <= bil < 2 ^ 47)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 bil ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 186336) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 188468) M' rom /\
      rinv [((s - 56)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 56)) 8 = Some (Z_to_le_bytes 8 bil) /\
      getr regs' 1 = Z_to_bv 64 186348 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 bil /\ regs_agree (fun r => In r [1]%list) regs regs').
