Lemma gr_C : forall (fx : FPState) regs (m : word -> option byte) (s r : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (0 <= r < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 r ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 186348) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 189076) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 186360 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 8 = Z_to_bv 64 r /\ getr regs' 10 = Z_to_bv 64 (s - 56) /\
      regs_agree (fun r => In r [1; 8; 10]%list) regs regs').
Proof.
